// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(address sender, address newLrtConfig) public {
        vm.assume(newLrtConfig != address(0));
        vm.assume(newLrtConfig != address(c.lrtConfig()));
        vm.assume(sender != address(0));
        vm.prank(sender);
        bool success;
        try c.updateLRTConfig(newLrtConfig) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == false || address(c.lrtConfig()) != newLrtConfig);
    }
}
